"""Dependency-free authenticated Marketplace page."""

# The inline HTML/CSS/JavaScript is shipped as one package-safe string.
# ruff: noqa: E501

PAGE = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shared Capability Marketplace</title>
<style>:root{--ink:#172033;--muted:#637083;--line:#dce2ea;--panel:#fff;--brand:#3157d5;--soft:#eef3ff;--ok:#16734a}*{box-sizing:border-box}body{font:15px/1.45 Inter,system-ui;margin:0;background:#f4f6fa;color:var(--ink)}main{max-width:1240px;margin:auto;padding:28px}header,.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:20px;margin-bottom:16px;box-shadow:0 2px 8px #1720330a}header{display:flex;justify-content:space-between;gap:20px}h1{font-size:25px;margin:0 0 5px}h2{font-size:18px;margin:0 0 12px}.muted{color:var(--muted)}.hidden{display:none!important}.account{text-align:right}.badge,.tag{display:inline-block;border-radius:99px;padding:3px 9px;background:var(--soft);color:var(--brand);font-size:12px;font-weight:700}.ok{color:var(--ok)}.grid,.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.filters{display:grid;grid-template-columns:1fr 160px 180px 220px;gap:9px;margin:14px 0}.field label{display:block;font-weight:650;margin-bottom:5px}.field input,.field select{width:100%;min-height:39px;border:1px solid #c9d1dc;border-radius:8px;padding:8px 10px;background:#fff}button{min-height:38px;border:1px solid #b9c4d3;border-radius:8px;padding:7px 12px;background:#fff;cursor:pointer;font-weight:650}button.primary{background:var(--brand);border-color:var(--brand);color:#fff}button.danger{color:#a22b2b}.status{padding:10px 12px;border-radius:9px;background:#f5f7fa;margin:10px 0}.card{border:1px solid var(--line);border-radius:11px;padding:14px;display:flex;justify-content:space-between;gap:12px}.card h3{margin:0 0 5px}.tags{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}.tag{color:#46536a;background:#f0f2f6;font-weight:500}.actions{min-width:130px;text-align:right}.empty{padding:20px;text-align:center;color:var(--muted);border:1px dashed var(--line);border-radius:10px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px;border-bottom:1px solid #e8ecf2;vertical-align:top}.admin-grid{display:grid;grid-template-columns:1.2fr .8fr .8fr .7fr auto;gap:8px;align-items:end}.invite-result{display:flex;gap:8px;margin-top:10px}.invite-result input{flex:1}.access-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;align-items:end}.manifest{max-height:420px;overflow:auto;background:#f5f7fa;border-radius:9px;padding:12px;font:12.5px/1.5 ui-monospace,Consolas,monospace;white-space:pre-wrap;word-break:break-word}@media(max-width:780px){main{padding:14px}header{display:block}.account{text-align:left}.grid,.cards,.filters,.admin-grid,.access-grid{grid-template-columns:1fr}table{display:block;overflow:auto}}</style></head>
<body><main><header><div><h1>Shared Capability Marketplace</h1><div class="muted">Discover governed Skills, Workflows, Extensions and Applications.</div></div><div id="account" class="account hidden"><strong id="actor"></strong> <span id="role" class="badge"></span><div><button id="sign-out">Sign out</button></div></div></header>
<section id="sign-in-panel" class="panel"><h2>Sign in with an invitation</h2><p class="muted">Open an invitation link once, or paste it here. This browser remembers a revocable login for later visits.</p><div class="grid"><div class="field"><label for="invitation">Invitation link or code</label><input id="invitation" autocomplete="off" placeholder="Paste the invitation link"></div><div><button id="sign-in" class="primary">Accept invitation and sign in</button></div></div><p id="sign-in-status" class="status">An administrator must invite each member.</p></section>
<div id="workspace" class="hidden"><section id="admin" class="panel hidden"><h2>Invitation administration</h2><p class="muted">Only platform administrators can invite members.</p><div class="admin-grid"><div class="field"><label for="invite-actor">Account</label><input id="invite-actor" placeholder="leo.chi" autocomplete="off" title="Letters, digits, . - _ only; no @"></div><div class="field"><label for="invite-role">Role</label><select id="invite-role"><option value="member">Member</option><option value="platform_admin">Administrator</option></select></div><div class="field"><label for="invite-groups">Groups</label><input id="invite-groups" placeholder="engineering, qa"></div><div class="field"><label for="invite-minutes">Minutes</label><input id="invite-minutes" type="number" min="1" max="10080" value="1440"></div><button id="create-invite" class="primary">Create invitation</button></div><p id="invite-rule" class="muted">Account: letters, digits, <code>.</code> <code>-</code> <code>_</code> only, starting with a letter; no <code>@</code> (for example <code>leo.chi</code>). Groups the same, separated by commas.</p><div id="invite-result" class="invite-result hidden"><input id="invite-url" readonly><button id="copy-invite">Copy link</button></div><div id="invitation-list" class="empty">Loading…</div></section>
<section id="review" class="panel hidden"><h2>Review queue</h2><p class="muted">Members publish Skills and Workflows from their Personal Agent. Read each one before you approve it; only an approval publishes it.</p><div class="field"><label for="review-status">Show</label><select id="review-status"><option value="pending">Waiting for review</option><option value="">All</option></select></div><table><thead><tr><th>Asset</th><th>Kind</th><th>From</th><th>Risk</th><th>Submitted</th><th>Status</th><th></th></tr></thead><tbody id="review-rows"></tbody></table><p id="review-status-text" class="muted"></p><div id="review-detail" class="hidden"><h3 id="review-title"></h3><p id="review-previous" class="muted"></p><pre id="review-manifest" class="manifest"></pre><div class="actions" style="text-align:left"><button id="review-approve" class="primary">Approve and publish</button> <button id="review-reject" class="danger">Reject</button> <button id="review-close">Close</button></div></div></section><section id="bridges" class="panel hidden"><h2>Bridges</h2><p class="muted">Computers whose Personal Agent enrolled itself. Disable withdraws a computer: its token stops working at once and its member cannot enroll it again without you.</p><table><thead><tr><th>Bridge</th><th>Member</th><th>Kind</th><th>Last enrolled</th><th>Token expires</th><th>Status</th><th></th></tr></thead><tbody id="bridge-rows"></tbody></table><p id="bridges-status" class="muted"></p></section><section id="published" class="panel"><h2 id="published-title">My published assets</h2><p class="muted">Skills and Workflows you own, or your team owns. Change who can use one at any time; published versions stay as they are. Members who already chose it keep it until they remove it.</p><div id="published-scope-field" class="field hidden"><label for="published-scope">Show</label><select id="published-scope"><option value="mine">Assets I own</option><option value="all">All published assets</option></select></div><table><thead><tr><th>Asset</th><th>Kind</th><th>Owner</th><th>Versions</th><th>Who can use it</th><th></th></tr></thead><tbody id="published-rows"></tbody></table><p id="published-status" class="muted"></p><div id="access-editor" class="hidden"><h3 id="access-title"></h3><div class="access-grid"><div class="field"><label for="access-visibility">Who can use it</label><select id="access-visibility"><option value="">As each version declares</option><option value="private">Only the owner</option><option value="team">Only the owning team</option><option value="organization">Everyone in the organization</option><option value="public">Public</option></select></div><div class="field"><label for="access-members">Also these members</label><input id="access-members" placeholder="leo.chi, anna" autocomplete="off"></div><div class="field"><label for="access-groups">Also these groups</label><input id="access-groups" placeholder="engineering, qa" autocomplete="off"></div></div><p id="access-effect" class="muted"></p><div class="actions" style="text-align:left"><button id="access-save" class="primary">Save</button> <button id="access-close">Close</button></div></div></section><section id="publishing" class="panel"><h2>Publish from your Personal Agent</h2><p class="muted">Your Agent publishes as you. Connect it once: the code is shown only here and now. Put it in the environment variable named in your Agent's settings, never in a file or a chat. It lasts 30 days; connect again for a new one.</p><button id="connect-agent">Connect a Personal Agent</button><div id="agent-login" class="invite-result hidden"><input id="agent-login-code" readonly><button id="copy-agent-login">Copy code</button></div><h3>My submissions</h3><table><thead><tr><th>Asset</th><th>Kind</th><th>Submitted</th><th>Status</th><th>Reviewer note</th></tr></thead><tbody id="mine-rows"></tbody></table><p id="mine-status" class="muted"></p></section><section class="panel"><h2>Agent Add-ons</h2><p class="muted">Selection makes an exact version available for this Bridge to synchronize. Runtime permission and installation remain separate checks.</p><div class="filters"><div class="field"><label for="search">Search</label><input id="search" placeholder="Name or description"></div><div class="field"><label for="kind">Kind</label><select id="kind"><option value="all">All kinds</option><option value="skill">Skills</option><option value="workflow">Workflows</option><option value="knowledge">Knowledge</option><option value="agent">Agent profiles</option></select></div><div class="field"><label for="category">Category</label><select id="category"><option value="all">All categories</option></select></div><div class="field"><label for="bridge">Bridge ID</label><input id="bridge" autocomplete="off" placeholder="bridge-id"></div></div><button id="load" class="primary">Load add-ons</button> <span id="status" class="muted"></span><div id="addon-cards" class="cards"></div></section>
<section id="extensions" class="panel hidden"><h2>Bridge Extensions</h2><p class="muted">Administrator view. Registry availability does not stage, activate or grant execution permission.</p><div id="extension-cards" class="cards"></div></section>
<section class="panel"><h2>Applications</h2><p id="application-status" class="muted">Loading…</p><table><thead><tr><th>Application</th><th>Owner</th><th>Repository</th><th>Release</th><th>Integrations</th></tr></thead><tbody id="application-rows"></tbody></table></section></div></main>
<script>const LOGIN_KEY="aep.marketplace.login.v1",BRIDGE_KEY="aep.marketplace.bridge.v1",fragment=new URLSearchParams(location.hash.slice(1));let bearer=fragment.get("session")||"",catalog=[];const invited=fragment.get("invitation")||"",fromAgent=fragment.get("bridge")||"",bootstrapLogin=fragment.get("login")||"";if(bootstrapLogin)localStorage.setItem(LOGIN_KEY,bootstrapLogin);if(location.hash)history.replaceState(null,"",location.pathname);const el=id=>document.getElementById(id);
async function renewSession(){const login=localStorage.getItem(LOGIN_KEY);if(!login)return false;try{const response=await fetch("/v1/member/session",{method:"POST",headers:{Authorization:`Login ${login}`}}),data=await response.json();if(!response.ok||!data.session)return false;bearer=data.session;return true}catch{return false}}
async function api(path,body={},authorization=""){const call=async()=>{const response=await fetch(path,{method:"POST",headers:{Authorization:authorization||`Bearer ${bearer}`,"Content-Type":"application/json"},body:JSON.stringify(body)});return[response,await response.json()]};let[response,data]=await call();if(!response.ok&&!authorization&&data.code==="session_expired"&&await renewSession())[response,data]=await call();if(!response.ok){const error=new Error(data.message||data.code||"request_failed");error.code=data.code;throw error}return data}
function invitationCode(value){const text=value.trim();if(!text)return"";try{const url=new URL(text,location.href);return new URLSearchParams(url.hash.slice(1)).get("invitation")||text}catch{return text}}
async function signIn(code){const response=await fetch("/v1/member/sign-in",{method:"POST",headers:{Authorization:`Invitation ${code}`}}),data=await response.json();if(!response.ok)throw new Error(data.code||"request_failed");bearer=data.session;localStorage.setItem(LOGIN_KEY,data.login);await openWorkspace()}
async function restore(){if(bearer)return true;const login=localStorage.getItem(LOGIN_KEY);if(!login)return false;try{bearer=(await api("/v1/member/session",{},`Login ${login}`)).session;return true}catch{localStorage.removeItem(LOGIN_KEY);return false}}
function signedOut(text="An administrator must invite each member."){bearer="";el("workspace").classList.add("hidden");el("account").classList.add("hidden");el("sign-in-panel").classList.remove("hidden");el("sign-in-status").textContent=text}
async function openWorkspace(){const me=await api("/v1/member/me");el("sign-in-panel").classList.add("hidden");el("workspace").classList.remove("hidden");el("account").classList.remove("hidden");el("actor").textContent=me.actor;el("role").textContent=me.role==="platform_admin"?"Administrator":"Member";const admin=me.role==="platform_admin";el("admin").classList.toggle("hidden",!admin);el("extensions").classList.toggle("hidden",!admin);el("review").classList.toggle("hidden",!admin);el("bridges").classList.toggle("hidden",!admin);if(admin)await Promise.all([loadInvitations(),loadExtensions(),loadQueue(),loadBridges()]);el("published-scope-field").classList.toggle("hidden",!admin);await loadMine();await loadPublished();await loadApplications();if(el("bridge").value)await loadAddons()}
async function loadApplications(){try{const data=await api("/v1/member/applications"),rows=el("application-rows");rows.textContent="";for(const app of data.applications){const id=app.identity,tr=document.createElement("tr");for(const value of [`${id.namespace}/${id.name}@${id.version}`,app.owner,`${app.repository_provider}:${app.repository_locator}`,app.release_ref,(app.integrations||[]).map(x=>x.name).join(", ")]){const td=document.createElement("td");td.textContent=value;tr.append(td)}rows.append(tr)}el("application-status").textContent=`${data.applications.length} Application(s); discovery is read-only.`}catch(error){el("application-status").textContent=`Applications unavailable: ${error.message}`}}
function updateCategories(){const values=[...new Set(catalog.flatMap(x=>x.package.metadata.categories||[]))].sort(),select=el("category"),old=select.value;select.innerHTML='<option value="all">All categories</option>';for(const value of values)select.add(new Option(value,value));select.value=values.includes(old)?old:"all"}
function renderAddons(){const search=el("search").value.trim().toLowerCase(),kind=el("kind").value,category=el("category").value,cards=el("addon-cards");cards.textContent="";const visible=catalog.filter(x=>{const p=x.package,id=p.metadata.identity,text=`${id.namespace} ${id.name} ${p.description||""}`.toLowerCase();return(!search||text.includes(search))&&(kind==="all"||p.kind===kind)&&(category==="all"||(p.metadata.categories||[]).includes(category))});if(!visible.length){cards.innerHTML='<div class="empty">No add-ons match these filters.</div>';return}for(const entry of visible){const p=entry.package,id=p.metadata.identity,card=document.createElement("article"),body=document.createElement("div"),actions=document.createElement("div");card.className="card";body.innerHTML='<h3></h3><div class="muted"></div><div class="tags"></div>';body.querySelector("h3").textContent=`${id.namespace}/${id.name}`;body.querySelector(".muted").textContent=p.description||`${p.kind} ${id.version}`;for(const value of [p.kind,...(p.metadata.categories||[])]){const tag=document.createElement("span");tag.className="tag";tag.textContent=value;body.querySelector(".tags").append(tag)}actions.className="actions";actions.innerHTML=`<div class="${entry.selected?"ok":"muted"}">${entry.selected?"Selected for Bridge":"Available"}</div>`;const button=document.createElement("button");button.textContent=entry.selected?"Remove selection":"Select for install";button.onclick=async()=>{await api(entry.selected?"/v1/member/revoke":"/v1/member/select",{bridge_id:el("bridge").value.trim(),asset:id});await loadAddons()};actions.append(button);card.append(body,actions);cards.append(card)}}
async function loadAddons(){const bridge=el("bridge").value.trim();if(!bridge){el("status").textContent="Enter the Bridge ID assigned to this Agent.";return}localStorage.setItem(BRIDGE_KEY,bridge);try{catalog=(await api("/v1/member/catalog",{bridge_id:bridge})).entries;updateCategories();renderAddons();el("status").textContent=`${catalog.length} entitled add-on(s)`}catch(error){catalog=[];renderAddons();el("status").textContent=`Unavailable: ${error.message}`}}
async function loadExtensions(){const cards=el("extension-cards");try{const data=await api("/v1/member/admin/extensions");cards.textContent="";for(const entry of data.entries){const p=entry.package,id=p.metadata.identity,card=document.createElement("article");card.className="card";card.innerHTML='<div><h3></h3><p class="muted"></p><div class="tags"></div></div><div class="actions"><span class="badge">Available</span><p class="muted">Bridge approval required</p></div>';card.querySelector("h3").textContent=`${id.namespace}/${id.name}@${id.version}`;card.querySelector("p").textContent=p.description||"Bridge Extension";for(const value of p.metadata.categories||[]){const tag=document.createElement("span");tag.className="tag";tag.textContent=value;card.querySelector(".tags").append(tag)}cards.append(card)}if(!data.entries.length)cards.innerHTML='<div class="empty">No governed Extensions are published.</div>'}catch(error){cards.innerHTML=`<div class="empty">Extensions unavailable: ${error.message}</div>`}}
async function loadInvitations(){const holder=el("invitation-list");try{const data=await api("/v1/member/admin/invitations/list");if(!data.invitations.length){holder.textContent="No invitations issued.";return}const table=document.createElement("table");table.innerHTML="<thead><tr><th>Account</th><th>Role</th><th>Groups</th><th>Status</th><th>Expires</th><th></th></tr></thead>";const body=document.createElement("tbody");for(const item of data.invitations){const inv=item.invitation,tr=document.createElement("tr");for(const value of [inv.actor,inv.role,inv.groups.join(", ")||"—",inv.status,new Date(item.expires_at).toLocaleString()]){const td=document.createElement("td");td.textContent=value;tr.append(td)}const action=document.createElement("td");if(inv.status==="pending"){const button=document.createElement("button");button.className="danger";button.textContent="Revoke";button.onclick=async()=>{await api("/v1/member/admin/invitations/revoke",{invitation_id:inv.invitation_id});await loadInvitations()};action.append(button)}tr.append(action);body.append(tr)}table.append(body);holder.replaceChildren(table)}catch(error){holder.textContent=`Invitations unavailable: ${error.message}`}}
el("sign-in").onclick=async()=>{const code=invitationCode(el("invitation").value);if(!code){el("sign-in-status").textContent="Paste the invitation link or code.";return}try{el("sign-in-status").textContent="Signing in…";await signIn(code)}catch(error){el("sign-in-status").textContent=`Sign in failed: ${error.message}`}};el("sign-out").onclick=()=>{localStorage.removeItem(LOGIN_KEY);signedOut("Signed out on this browser.")};el("load").onclick=loadAddons;el("search").oninput=renderAddons;el("kind").onchange=renderAddons;el("category").onchange=renderAddons;
const ACCOUNT=/^[a-zA-Z_][a-zA-Z0-9_.-]*$/;function nameProblem(account,groups){if(!ACCOUNT.test(account))return"Account: letters, digits, . - _ only, starting with a letter; no @ (for example leo.chi).";if(groups.some(g=>!ACCOUNT.test(g)))return"Groups: letters, digits, . - _ only, separated by commas; no @ or spaces.";return""}
el("create-invite").onclick=async()=>{const groups=el("invite-groups").value.split(",").map(x=>x.trim()).filter(Boolean),problem=nameProblem(el("invite-actor").value.trim(),groups);if(problem){el("invite-url").value=problem;el("invite-result").classList.remove("hidden");return}try{const data=await api("/v1/member/admin/invitations",{actor:el("invite-actor").value.trim(),role:el("invite-role").value,groups,valid_for_minutes:Number(el("invite-minutes").value)});el("invite-url").value=data.url;el("invite-result").classList.remove("hidden");await loadInvitations()}catch(error){el("invite-url").value=`Could not create invitation: ${error.message}`;el("invite-result").classList.remove("hidden")}};el("copy-invite").onclick=async()=>{await navigator.clipboard.writeText(el("invite-url").value);el("copy-invite").textContent="Copied"};el("bridge").value=fromAgent||localStorage.getItem(BRIDGE_KEY)||"";if(invited)el("invitation").value=invited;
(async()=>{try{if(invited){await signIn(invited);return}if(await restore()){await openWorkspace();return}signedOut()}catch(error){localStorage.removeItem(LOGIN_KEY);signedOut(`Sign in failed: ${error.message}`)}})();
function cell(row,value){const td=document.createElement("td");td.textContent=value;row.append(td);return td}
const assetName=s=>`${s.identity.namespace}/${s.identity.name}@${s.identity.version}`,when=t=>t?new Date(t).toLocaleString():"";
async function loadMine(){const rows=el("mine-rows");try{const data=await api("/v1/member/assets/submissions");rows.textContent="";for(const s of data.submissions){const tr=document.createElement("tr");for(const v of [assetName(s),s.kind,when(s.submitted_at),s.status,s.reason||""])cell(tr,v);rows.append(tr)}el("mine-status").textContent=data.submissions.length?"":"Nothing submitted yet."}catch(error){el("mine-status").textContent=`Submissions unavailable: ${error.message}`}}
let reviewing=null;
async function loadQueue(){const rows=el("review-rows"),status=el("review-status").value;try{const data=await api("/v1/member/admin/submissions/list",status?{status}:{});rows.textContent="";for(const s of data.submissions){const tr=document.createElement("tr");for(const v of [assetName(s),s.kind,s.submitter,s.risk,when(s.submitted_at),s.status])cell(tr,v);const td=cell(tr,""),view=document.createElement("button");view.textContent="View";view.onclick=()=>openReview(s.submission_id);td.append(view);rows.append(tr)}el("review-status-text").textContent=data.submissions.length?"":"No submissions here."}catch(error){el("review-status-text").textContent=`Review queue unavailable: ${error.message}`}}
async function openReview(id){const data=await api("/v1/member/admin/submissions/get",{submission_id:id}),s=data.submission;reviewing=s;el("review-title").textContent=`${assetName(s)} from ${s.submitter}`+(s.note?` — ${s.note}`:"");el("review-previous").textContent=data.previous_version?`Published before: ${data.previous_version}. Permissions it asks for: ${(s.required_permissions||[]).join(", ")||"none"}.`:`A new name. Permissions it asks for: ${(s.required_permissions||[]).join(", ")||"none"}.`;el("review-manifest").textContent=JSON.stringify(data.manifest,null,2);const open=s.status==="pending";el("review-approve").disabled=!open;el("review-reject").disabled=!open;el("review-detail").classList.remove("hidden");el("review-detail").scrollIntoView({block:"nearest"})}
async function decide(kind){if(!reviewing)return;const text=prompt(kind==="approve"?"What did you check? (kept with the approval)":"Why is it rejected? (the member sees this)");if(!text||!text.trim())return;try{await api(`/v1/member/admin/submissions/${kind}`,kind==="approve"?{submission_id:reviewing.submission_id,evidence:text.trim()}:{submission_id:reviewing.submission_id,reason:text.trim()});el("review-detail").classList.add("hidden");reviewing=null;el("review-status-text").textContent=kind==="approve"?"Approved and published.":"Rejected."}catch(error){el("review-status-text").textContent=`Could not ${kind}: ${error.message}`}await loadQueue()}
el("review-approve").onclick=()=>decide("approve");el("review-reject").onclick=()=>decide("reject");el("review-close").onclick=()=>{el("review-detail").classList.add("hidden");reviewing=null};el("review-status").onchange=loadQueue;
el("connect-agent").onclick=async()=>{try{const data=await api("/v1/member/logins/issue-agent");el("agent-login-code").value=data.login;el("agent-login").classList.remove("hidden")}catch(error){el("agent-login-code").value=`Could not connect: ${error.message}`;el("agent-login").classList.remove("hidden")}};el("copy-agent-login").onclick=async()=>{await navigator.clipboard.writeText(el("agent-login-code").value);el("copy-agent-login").textContent="Copied"};
async function loadBridges(){const rows=el("bridge-rows");try{const data=await api("/v1/member/admin/bridges/list");rows.textContent="";for(const b of data.bridges){const tr=document.createElement("tr");for(const v of [b.bridge_id,(b.members||[]).join(", ")||b.registered_by,b.device_kind,when(b.enrolled_at),when(b.token_expires_at)||"—",b.status])cell(tr,v);const td=cell(tr,"");if(b.status==="active"){const off=document.createElement("button");off.className="danger";off.textContent="Disable";off.onclick=async()=>{if(!confirm(`Disable ${b.bridge_id}? Its token stops working now.`))return;try{await api("/v1/member/admin/bridges/disable",{bridge_id:b.bridge_id});el("bridges-status").textContent=`${b.bridge_id} disabled.`}catch(error){el("bridges-status").textContent=`Could not disable: ${error.message}`}await loadBridges()};td.append(off)}rows.append(tr)}if(!data.bridges.length)el("bridges-status").textContent="No computer is enrolled yet."}catch(error){el("bridges-status").textContent=`Bridges unavailable: ${error.message}`}}
const AUDIENCE={private:"Only the owner",team:"Only the owning team",organization:"Everyone in the organization",public:"Public"},ownerName=o=>o.type==="user"?o.id:`${o.id} (${o.type})`,listOf=v=>v.split(",").map(x=>x.trim()).filter(Boolean);
function audience(e){const extra=e.access?[...e.access.members,...e.access.groups.map(g=>`group ${g}`)]:[];return AUDIENCE[e.visibility]+(extra.length?` + ${extra.join(", ")}`:"")}
let editing=null;
async function loadPublished(){const rows=el("published-rows"),scope=el("published-scope").value;el("published-title").textContent=scope==="all"?"All published assets":"My published assets";try{const data=await api("/v1/member/assets/access",{scope});rows.textContent="";for(const e of data.entries){const tr=document.createElement("tr");for(const v of [`${e.namespace}/${e.name}`,e.kind,ownerName(e.owner),e.versions.join(", "),audience(e)])cell(tr,v);const td=cell(tr,""),edit=document.createElement("button");edit.textContent="Who can use it";edit.onclick=()=>openAccess(e);td.append(edit);rows.append(tr)}el("published-status").textContent=data.entries.length?"":"Nothing published yet."}catch(error){el("published-status").textContent=`Published assets unavailable: ${error.message}`}}
function accessEffect(){if(!editing)return;const v=el("access-visibility").value||editing.declared_visibility,team=editing.owner.type==="user"?"The owner is a person, so the owning team is only them: add members or groups to share it.":`The owning team is ${editing.owner.id}.`;el("access-effect").textContent=`${AUDIENCE[v]} can use every version, plus the members and groups listed. ${team}`}
function openAccess(e){editing=e;el("access-title").textContent=`Who can use ${e.namespace}/${e.name}`;el("access-visibility").value=e.access&&e.access.visibility?e.access.visibility:"";el("access-members").value=e.access?e.access.members.join(", "):"";el("access-groups").value=e.access?e.access.groups.join(", "):"";el("access-visibility").options[0].textContent=`As each version declares (${AUDIENCE[e.declared_visibility]})`;accessEffect();el("access-editor").classList.remove("hidden");el("access-editor").scrollIntoView({block:"nearest"})}
el("access-visibility").onchange=accessEffect;el("published-scope").onchange=loadPublished;el("access-close").onclick=()=>{el("access-editor").classList.add("hidden");editing=null};
el("access-save").onclick=async()=>{if(!editing)return;const members=listOf(el("access-members").value),groups=listOf(el("access-groups").value),problem=members.some(m=>!ACCOUNT.test(m))?"Members: account names use letters, digits, . - _ only; no @.":groups.some(g=>!ACCOUNT.test(g))?"Groups: letters, digits, . - _ only; no @ or spaces.":"";if(problem){el("access-effect").textContent=problem;return}try{await api("/v1/member/assets/access/update",{namespace:editing.namespace,name:editing.name,visibility:el("access-visibility").value||null,members,groups});el("access-editor").classList.add("hidden");editing=null}catch(error){el("access-effect").textContent=error.code==="not_name_owner"?"Only the owner, a member of the owning team or an administrator can change this.":`Could not save: ${error.message}`;return}await loadPublished();el("published-status").textContent="Saved."};
</script></body></html>"""
